mapper.select:
SELECT

    CONCAT_WS(':', platform, bot_id, group_id)
    slot_code
    model_id
    DATE_FORMAT(created_at, '%Y-%m-%d')

AS dimensionKey,
COUNT(*) AS calls,
COALESCE(SUM(input_tokens), 0) AS inputTokens,
COALESCE(SUM(output_tokens), 0) AS outputTokens,
COALESCE(SUM(cached_tokens), 0) AS cachedTokens,
COALESCE(SUM(cost_amount), 0) AS costAmount
FROM llm_call_log
WHERE is_replay = 0
AND created_at >= #{from}
AND created_at <= #{to}
AND group_id = #{groupId}
AND platform = #{platform}
AND bot_id = #{botId}
AND slot_code = #{slotCode}
AND model_id = #{modelId}
GROUP BY 1
ORDER BY 1

SELECT COUNT(*) AS calls,
COALESCE(SUM(input_tokens), 0) AS inputTokens,
COALESCE(SUM(output_tokens), 0) AS outputTokens,
COALESCE(SUM(cached_tokens), 0) AS cachedTokens,
COALESCE(SUM(cost_amount), 0) AS costAmount
FROM llm_call_log
WHERE is_replay = 0
AND created_at >= #{from}
AND created_at <= #{to}
AND group_id = #{groupId}

SELECT ttft_ms
FROM llm_call_log
WHERE ttft_ms IS NOT NULL
AND is_replay = 0
AND created_at >= #{from}
AND created_at <= #{to}
AND group_id = #{groupId}

SELECT MAX(id)
FROM llm_call_log
WHERE run_kind = #{runKind}
